            living_cost_outside_london: [''],
            total_fund: [{ value: 0, disabled: true }],
            living_cost_plan: this.fb.control([]),
            otherSelected: [false],
            other: [''],
            education_loan: [''],
            loan_doc: [''],
            another_education_loan: [''],
            another_loan_doc: [''],
            fees_deposit: [''],
            deposit_doc: [''],
            another_deposit: [''],
